#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <random>
#include <sstream>
#include <string>
#include <vector>
using namespace std;
class User{protected:int id;string name,email,role;public:User(int i,string n,string e,string r):id(i),name(move(n)),email(move(e)),role(move(r)){}virtual~User()=default;virtual void displayProfile()const{cout<<id<<" | "<<name<<" | "<<email<<" | "<<role<<'\n';}};class Admin:public User{public:Admin(int i,string n,string e):User(i,move(n),move(e),"Admin"){} };class Student:public User{public:Student(int i,string n,string e):User(i,move(n),move(e),"Student"){} };
class Question{protected:int qid;string text;int points;public:Question(int i,string t,int p):qid(i),text(move(t)),points(p){}virtual~Question()=default;int getId()const{return qid;}int getPoints()const{return points;}virtual void displayQuestion()const=0;virtual bool askAndCheck()const=0;virtual string serialize()const=0;};
class MCQQuestion:public Question{vector<string> options;int correct;public:MCQQuestion(int i,string t,int p,vector<string>o,int c):Question(i,move(t),p),options(move(o)),correct(c){}void displayQuestion()const override{cout<<text<<" ["<<points<<" pts]\n";for(size_t i=0;i<options.size();++i)cout<<i+1<<") "<<options[i]<<'\n';}bool askAndCheck()const override{displayQuestion();int a;cout<<"Answer: ";cin>>a;return a==correct;}string serialize()const override{ostringstream o;o<<"M|"<<qid<<'|'<<points<<'|'<<text<<'|'<<correct<<'|';for(size_t i=0;i<options.size();++i){if(i)o<<';';o<<options[i];}return o.str();}};
class TrueFalseQuestion:public Question{bool correct;public:TrueFalseQuestion(int i,string t,int p,bool c):Question(i,move(t),p),correct(c){}void displayQuestion()const override{cout<<text<<" (1=True, 0=False) ["<<points<<" pts]\n";}bool askAndCheck()const override{displayQuestion();int a;cout<<"Answer: ";cin>>a;return (a!=0)==correct;}string serialize()const override{return string("T|")+to_string(qid)+"|"+to_string(points)+"|"+text+"|"+(correct?"1":"0");}};
class Quiz{int id;string title;vector<shared_ptr<Question>>qs;public:Quiz(int i=0,string t=""):id(i),title(move(t)){}int getId()const{return id;}const string&getTitle()const{return title;}void add(shared_ptr<Question>q){qs.push_back(move(q));}const auto&questions()const{return qs;}int take()const{vector<size_t>order(qs.size());for(size_t i=0;i<order.size();++i)order[i]=i;shuffle(order.begin(),order.end(),mt19937(random_device{}()));int score=0,total=0;for(auto i:order){bool ok=qs[i]->askAndCheck();total+=qs[i]->getPoints();if(ok)score+=qs[i]->getPoints();cout<<(ok?"Correct.\n":"Incorrect.\n");}cout<<"Score: "<<score<<"/"<<total<<'\n';return score;}};
class QuizSystem{vector<Quiz>quizzes;int nextQuiz=1,nextQ=1;Quiz*findQuiz(int id){for(auto&q:quizzes)if(q.getId()==id)return&q;return nullptr;}public:QuizSystem(){Quiz q(nextQuiz++,"C++ Basics");q.add(make_shared<MCQQuestion>(nextQ++,"Which keyword creates a class?",1,vector<string>{"class","object","new","type"},1));q.add(make_shared<TrueFalseQuestion>(nextQ++,"Encapsulation hides implementation details.",1,true));quizzes.push_back(q);}void list()const{for(auto&q:quizzes)cout<<q.getId()<<" | "<<q.getTitle()<<" | "<<q.questions().size()<<" questions\n";}void create(){string t;cout<<"Title: ";cin>>ws;getline(cin,t);quizzes.emplace_back(nextQuiz++,t);}void addQuestion(){int id;cout<<"Quiz ID: ";cin>>id;auto*q=findQuiz(id);if(!q)return;int type,p;string t;cout<<"Type 1 MCQ 2 T/F, points: ";cin>>type>>p;cout<<"Text: ";cin>>ws;getline(cin,t);if(type==1){int n,c;cout<<"Options count: ";cin>>n;vector<string>o(n);for(int i=0;i<n;++i){cin>>ws;getline(cin,o[i]);}cout<<"Correct option: ";cin>>c;q->add(make_shared<MCQQuestion>(nextQ++,t,p,o,c));}else{int c;cout<<"Correct 1/0: ";cin>>c;q->add(make_shared<TrueFalseQuestion>(nextQ++,t,p,c));}}void take(){list();int id;cout<<"Quiz ID: ";cin>>id;if(auto*q=findQuiz(id)){int score=q->take();ofstream("results.txt",ios::app)<<id<<'|'<<score<<'\n';}}void run(){for(;;){cout<<"\nQuiz App\n1 View quizzes 2 Create quiz 3 Add question 4 Take quiz 5 Results 0 Exit\nChoice: ";int c;if(!(cin>>c)||c==0)break;if(c==1)list();else if(c==2)create();else if(c==3)addQuestion();else if(c==4)take();else if(c==5){ifstream f("results.txt");string l;while(getline(f,l))cout<<l<<'\n';}}}};int main(){QuizSystem{}.run();}
